with open('surface_energy.log', 'rb') as file:
    content = file.read()
    # Search for the surface energy line
    start = content.find(b'Surface energy =')
    if start != -1:
        end = content.find(b'\n', start)
        line = content[start:end].decode('utf-8', errors='ignore')
        print(line.split('=')[1].strip())
    else:
        print('Surface energy not found')
